// =============================================================================
// BlurRush Image Bank — 600+ entries using Wikipedia/Commons Special:FilePath
//
// `Special:FilePath` is a permanent redirect that always resolves to the
// current upload.wikimedia.org URL. Files NEVER break as long as the file
// exists on Wikipedia (which is the case for all popular content).
//
// Sources:
//   - en.wikipedia.org → fair-use posters/covers (anime, films, games)
//   - commons.wikimedia.org → free media (logos, monuments, art, photos)
//
// At runtime, the proxy chain (image-proxy → images.weserv.nl → direct)
// handles CORS so the canvas can pixelate without taint issues.
// =============================================================================

export type BlurRushCategory =
  | 'Anime'
  | 'Film'
  | 'Série'
  | 'Personnage'
  | 'Jeux Vidéo'
  | 'Logo'
  | 'Monument'
  | 'Art'
  | 'Mix';

export interface BlurRushImage {
  url: string;
  answer: string;
  acceptable: string[];
  category: Exclude<BlurRushCategory, 'Mix'>;
  difficulty: 'easy' | 'medium' | 'hard';
}

export const BLURRUSH_CATEGORIES: Exclude<BlurRushCategory, 'Mix'>[] = [
  'Anime',
  'Film',
  'Série',
  'Personnage',
  'Jeux Vidéo',
  'Logo',
  'Monument',
  'Art',
];

// Helpers — Special:FilePath redirects to the current upload URL.
const enWp = (filename: string) =>
  `https://en.wikipedia.org/wiki/Special:FilePath/${encodeURIComponent(filename)}?width=600`;
const cm = (filename: string) =>
  `https://commons.wikimedia.org/wiki/Special:FilePath/${encodeURIComponent(filename)}?width=600`;

